<?php
$zipData = base64_decode('');
file_put_contents('deploy.zip', $zipData);
$zip = new ZipArchive;
if ($zip->open('deploy.zip') === TRUE) {
    $zip->extractTo('../');
    $zip->close();
    unlink('deploy.zip');
    echo '<h1>Session Auto-Lock & Logout Deployed!</h1>';
    echo '<p>PIN Lock and Logout button successfully installed.</p>';
} else {
    echo '<h1>Error extracting zip</h1>';
}
?>